	\centering
	\def \svgwidth{.5\columnwidth}
	\input{fusion2.pdf_tex}
	\caption{The fusion rules. Black edges are colored by $1$ and $\varepsilon,\eta\in \lbrace \pm 1 \rbrace.$ The first, second and third equations will be refered to as the merge rule, the half-twist rule and the triangle rule. All colorings are admissible.}
	\label{fig:fusion}
\end{figure}
We will need the following in order to establish Lemmas \ref{lemma:curveActions} and \ref{lemma:longcurveactions}:
\begin{lemma}
	\label{lemma:come-back}
	We have for $(a,b,c)$ an admissible triple and $\varepsilon,\eta\in \lbrace \pm 1\rbrace:$
	\begin{center}
		\def\svgwidth{0.58\columnwidth}
	\input{come-back-pattern.pdf_tex}
	\end{center}
	where $F_{\varepsilon,\eta}\in \Q(A,X_1,X_2,X_3)$ and $F_{\varepsilon,\varepsilon}(A,A^a,A^b,A^c)\neq 0$ if $(a,b,c+2\varepsilon)$ is admissible.
\end{lemma}
We will call the pattern on the left hand side of Lemma \ref{lemma:come-back} a \emph{come-back pattern}.
\begin{proof}
	This is achieved by a straightforward application of the fusion rules. First we merge the black loop with the edge colored by $a$; thus we can remove the two crossings with two half-twist moves. The resulting graph will have two concentric triangular faces that can be removed with two triangle rules. In formulas, we have that $C(a,b,c,\epsilon,\eta)$ is equal to

	$$\left(\sum_{\delta\in\{\pm 1\}} t(a,\delta)^2T(b,a,c,\delta,\epsilon)T(b,a+\delta,c+\epsilon,-\delta,\eta)\right)Y(a,b,c+\epsilon+\eta)$$

	where $C(a,b,c,\epsilon,\eta)$ is the come-back pattern and $Y(a,b,c)$ is the vertex colored by $a,b,c+\epsilon+\eta$. The fact that the sum does not cancel out can be either verified directly for each choice of $\epsilon,\eta$ or deduced from the fact that $t(a,1)=A^a,t(a,-1)=A^{-(a+2)}$ and everything else is symmetric under $A\ra A^{-1}$.
\end{proof}
\begin{proof}[Proof of Lemmas \ref{lemma:curveActions} and \ref{lemma:longcurveactions}]
	We note that curves $\beta_e$ where $e$ is a non-loop edge are a special case of curves of the type $\beta_{\gamma},$ so there will be $3$ types of curves to consider to prove both lemmas: curves $\alpha_e,$ curves $\beta_e$ where $e$ is a loop edge, and curves $\beta_{\gamma}$ where $\gamma$ is an arc of consecutive non-loop edges.

	For the curves $\alpha_e,$ one has $T^{\alpha_e}\varphi_c=(-A^{2+2c(e)}-A^{-2-2c(e)})\varphi_c,$ by the basic properties of Jones-Wenzl idempotents.

	In the case where $e$ is a loop edge, one can compute $T^{\beta_e}\varphi_c$ by first merging $\beta_e$ with $e,$ then simplifying the resulting triangles. Let $f\neq e$ be the edge adjacent to $e.$ One gets that $T^{\beta_e}\varphi_{c}$ is equal to
	\begin{multline*}M_+(c(e))T(c(f),c(e),c(e),1,1)\varphi_{c+\delta_e}+M_-(c(e))T(c(f),c(e),c(e),-1,-1)\varphi_{c-\delta_e}
		\\ =\varphi_{c+\delta_e}+ \frac{ \lbrace c(e)+\frac{c(f)}{2}+1 \rbrace \lbrace c(e)-\frac{c(f)}{2} \rbrace}{\lbrace c(e)\rbrace \lbrace c(e)+1\rbrace}\varphi_{c-\delta_e}.
		\end{multline*}
	It is then clear that the coefficient in $\varphi_{c+\delta_e}$ is non-zero, and the coefficient in $\varphi_{c-\delta_e}$ is too, since if $c-\delta_e$ is admissible then $c(e)-\frac{c(f)}{2}>0.$

	Finally, let $e_1,\ldots,e_n$ be a sequence of consecutive non-loop edges, forming an arc $\gamma.$ Let $f_i$ be the third edge adjacent to the trivalent vertex common to $e_i$ and $e_{i+1}.$ Similarly, let $f_0,f_0',f_n,f_n'$ be the edges adjacent to the endpoints of $\gamma,$ with $f_0,f_0'$ adjacent to $e_1$ and $f_n,f_n'$ adjacent to $e_n$ (we don't require them to be different). To compute $T^{\beta_{\gamma}}\varphi_c,$ one uses the merging rule twice for each edge $e_i$, then, possibly after applying some half-twist rules, one is left with getting rid of $2$ triangles supported by edges $i$ and $i+1$ for $1\leq i \leq n-1,$ plus a come-back pattern for each extremity of $\gamma.$ At the end, $T^{\beta_{\gamma}}\varphi_c$ will be a linear combination of the $\varphi_{c'},$ where $c'=c+\sum \varepsilon_i \delta_{e_i}$ for some $\varepsilon_i \in \lbrace 0, \pm 2 \rbrace.$ Indeed, merging one strand colored by $1$ shifts the color by $\pm 1.$	
	Furthermore, it is clear by the fusion rules and by Lemma \ref{lemma:come-back} that the coefficient $F_{c'}$ is a rational fraction in $A$ and the $A^{c(e)}$'s for $e\in \mathcal{E}.$ (in fact, $e=e_i$ for some $i,$ or $e$ adjacent to some $e_i$)

	Let us focus on the coefficient in $c'=c+\sum \varepsilon_i \delta_{e_i}$ when $\varepsilon_i\in \lbrace \pm 2 \rbrace$ for all $1\leq i \leq n,$ assuming that $c'$ is admissible. Then one needs to merge twice with the same sign at each edge to get $\varphi_c',$ hence $F_{c'}$ is a sum of one term. More precisely,


	\begin{multline*}F_{c'}=\left(\underset{1\leq i \leq n}{\prod}M_{\varepsilon_i}(c(e_i))\right)		 
		\\ \times \left(\underset{1\leq i \leq n-1}{\prod}T(c(f_i),c(e_i),c(e_{i+1}),\varepsilon_i,\varepsilon_{i+1})T(c(f_i),c(e_i)+\varepsilon_i,c(e_{i+1})+\varepsilon_{i+1},\varepsilon_i,\varepsilon_{i+1})\right)
		\\ \times F_{\varepsilon_1,\varepsilon_1}(A,A^{c(f_0)},A^{c(f_{0}')},A^{c(e_1)})F_{\varepsilon_n,\varepsilon_n}(A,A^{c(f_n)},A^{c(f_{n}')},A^{c(e_n)}),
\end{multline*}
	possibly up to half-twist coefficients, which are of the form $\pm A^k,$ hence non-zero. 
	Note that, for any $\varepsilon \in \lbrace \pm 1 \rbrace,$ the triangle coefficient $T(a,b,c,\varepsilon,\eta)$ is non-zero whenever $(a,b,c)$ and $(a+\varepsilon,b+\eta,c)$ are admissible triples. It is clear when $\varepsilon=\eta=+1.$ When $\varepsilon=\eta=-1$ we have $b+c-a\geq 2$ because $(a,b-1,c-1)$ is admissible, so it is true also. The other two cases are similar. 
	This implies that the triangle coefficients in $F_{c'}$ are all non-zero: indeed if $(c(e_i),c(e_{i+1}),c(f_i))$ and $(c(e_i)+2\varepsilon_i,c(e_{i+1})+2\varepsilon_{i+1},c(f_i))$ are admissible (as implied by the admissibility of $c$ and $c'$) then so is $(c(e_i)+\varepsilon_i,c(e_{i+1})+\varepsilon_{i+1},c(f_i)).$
	 Finally, by Lemma \ref{lemma:come-back}, the factors coming from come-back patterns are also non-zero. 
\end{proof}
\subsection{Minimal shifts}
\label{sec:min-shifts}
The following definitions of shifts and minimal shifts are implicit in Proposition 2.3 and Lemma 2.4 of\cite{DS25}. Recall that a subset of $\Z^ \mathcal{E}$ is \emph{large} if it contains a subset of the form $\cap_{i=1}^{3g-3} \left(c_i+\Delta\right)$, where the $c_i$s are any coloring of $\Gamma$ such that the sum of colors around each vertex is even.
\begin{definition}
	Consider $M$ a monomial in the curve operators. For any $\varphi_c$ basis element of $Sk(H)$, we can apply $M$ to $\varphi_c$; by \cite[Proposition 2.3]{DS25} for $c$ in a large subset, \begin{equation}\label{eqn:operatorformula}M \varphi_c=\sum_{x\in\Z^{\mathcal{E}}}F_x(A^{c(e_1)},\dots,A^{c(e_{3g-3})})\varphi_{c+x},\end{equation} where only a finite number of the $F_x$'s are non-zero. By \cite[Lemma 2.4]{DS25}, the $x$'s for which $F_x\neq 0$ do not depend on the large subset chosen (i.e. it only depends on $M$).  

	We say that $x\in \Z^{\mathcal{E}}$ is a \emph{shift for $M$} if $F_x\neq 0$ in the above formula. Fix $k\geq 0,$ an order relation on $\Z^k$ and a group morphism $f:\Z^{\mathcal{E}}\longrightarrow \Z^k.$ We say that $x$ is \emph{a minimal shift for $M$ with respect to $f$} if and only if $f(x)$ is minimal among all shifts of $M$.

	We say that an admissible coloring $c$ is \emph{effective} for $M$ if for some minimal shift $x$ of $M$, $c-x$  belongs to a large subset such that \eqref{eqn:operatorformula} holds.	
\end{definition}

Notice that the definition of the minimal shift relies on the choice of $f$; in what follows we will only ever use one choice of $f$ at a time, so we will mostly omit to mention it.

\begin{definition}
	Consider a monomial $M$ in the curve operators, and suppose $x_1,\dots,x_n$ are the minimal shifts of $M$. Then call $\mathcal{P}_M$, the \emph{polytope of minimal shifts of $M$}, the convex hull of $x_1,\dots,x_n$.
\end{definition}

\begin{lemma}\label{lemma:uniqueminimalshift}
	Suppose $M_1$ and $M_2$ are two monomials in the curve operators. Suppose that for any $x$ minimal shift of either of them, $f(x)$ is non-positive. Furthermore suppose that either
	\begin{itemize}
		\item $M_1$ has a unique minimal shift; or
		\item the polytope of minimal shifts of $M_1$ and $M_2$ belong to subspaces that intersect only in $0$.
	\end{itemize}
	Then, the minimal shifts of $M_1M_2$ are exactly $y_1+y_2$, where $y_1$ and $y_2$ are minimal shifts of $M_1$ and $M_2$ respectively.
\end{lemma}
\begin{proof}
	Write $M_2\varphi_c=\sum_x F_x \varphi_{c+x}$ as in Equation \eqref{eqn:operatorformula}, and choose $c$ large enough that for all shifts of $M_2$, Equation \eqref{eqn:operatorformula} also applies to $M_1\varphi_{c+x}$. Then,
	\begin{equation}\label{eqn:productformula}M_1M_2\varphi_c=\sum_{x_1,x_2} F_{x_1}F_{x_2} \varphi_{c+x_1+x_2}\end{equation}
	where the sum is over all shifts $x_1,x_2$ of $M_1,M_2$ respectively. Take $y_1,y_2$ minimal shifts of $M_1,M_2$. First notice that $y_1+y_2$ can appear only once in Equation \eqref{eqn:productformula}; suppose by contradiction that there are $x_1,x_2$ different shifts of $M_1,M_2$ such that $y_1+y_2=x_1+x_2$. This implies that $f(x_1+x_2)=f(y_1+y_2)$ and by minimality and non-positivity, $f(x_1)=f(y_1)$ and $f(x_2)=f(y_2)$ which means that $x_1,x_2$ are minimal shifts for $M_1,M_2$. Then, if $M_1$ has a unique minimal shift, we find that $x_1=y_1$ and thus $x_2=y_2$. If instead the condition about the polytope of minimal shifts holds, we have that $x_1-y_1=y_2-x_2$ and thus must be $0$, obtaining once again that $x_1=y_1$ and $x_2=y_2$. Therefore $y_1+y_2$ appears only once in Equation \eqref{eqn:productformula} with coefficient $F_{y_1}F_{y_2}\neq 0$. It is immediate to see that $y_1+y_2$ must be minimal, and that if either $x_1$ or $x_2$ is not minimal, $x_1+x_2$ cannot be minimal either.
\end{proof}
\begin{corollary}\label{cor:uniqueminimalshift}
	Take some curve operators $T_i$. Suppose that they all have a unique minimal shift $x_i$ with respect to $f$, and suppose furthermore that the $f(x_i)$'s are linearly independent. Then any monomial in the $T_i$'s will also have a unique minimal shift with respect to $f$, equal to the sum (with multiplicity) of the minimal shifts of the $T_i$'s.
\end{corollary}
\begin{proof}
	Suppose $M$ is a monomial in $T_1,\dots,T_n$, and suppose that $T_i$ appears in $M$ with multiplicity $k_i\geq 0$. Then $x=\sum_i k_i x_i$ is a minimal shift for $M$, since the shifts of $M$ are all sums of shifts of the $T_i$'s. Notice that because the $f(x_i)$'s are linearly independent, so are the $x_i$'s, which implies that as we apply each $T_i$, there is only one way to obtain $x$ in the expansion of $M\cdot \varphi_c$. This implies that $F_x$ is simply a product of the $F_{x_i}$'s, and thus is non-zero.

	 Suppose that $y$ is also a minimal shift of $M$, i.e. $y$ is a shift of $M$ and $f(y)=f(x)$. Because $y$ must be a sum of shifts of the $T_i$'s, it must by minimality be of the form $\sum_i h_i x_i$. Therefore $f(y)=f(x)$ implies $\sum_i(h_i-k_i)x_i=0$ which means $h_i=k_i$ for all $i$ and $y=x$.
\end{proof}


\begin{lemma}\label{lemma:effectiveness}
	If $c$ is an effective coloring for $M$, and $y$ is a non-negative coloring of $\Gamma$ such that $c+y$ is admissible, then $c+y$ is an effective coloring for $M$.
\end{lemma}
\begin{proof}
	This is an obvious consequence of the definition of effectiveness and of a large subset.
\end{proof}
\begin{corollary}\label{cor:effectiveness}
	If $c$ is an effective coloring for $M_1$ and $M_2$, and the minimal shift $y$ of $M_2$ is non-positive, then $c$ is an effective coloring for $M_1M_2$.
\end{corollary}


\section{Some preliminary lemmas}
\label{sec:prelim-lemmas}
We are almost ready to start the proof of Theorem \ref{thm:main}, but will need a few additional lemmas. The content of this section is elementary and does not use previous sections. The first two lemmas, Lemma \ref{lemma:non-vanishing_poly} and Lemma \ref{lemma:lin_alg} will help us choose the curves of type $\alpha_e$ and $\beta_e$ to which we will apply Lemma \ref{lem:linDep} in the next section. 

\begin{lemma}
	\label{lemma:non-vanishing_poly} Let $D\geq 1,$ and let $V$ be an affine sub-lattice of $\mathbb{Z}^D$ of rank $k.$ Then there is a subset $I=\lbrace i_1<\ldots< i_k \rbrace\subset \lbrace 1,\ldots,D \rbrace$ such that, for any non-zero Laurent polynomial $P\in \mathbb{Q}[A^{\pm 1}][X_1^{\pm 1},\ldots,X_k^{\pm 1}],$ the function 
	$$c\in \mathbb{Z}^D \longrightarrow P(A^{c_{i_1}},\ldots ,A^{c_{i_k}})$$
	is non-vanishing on the complement in $V$ of a finite union of sublattices of rank $<k.$
\end{lemma}
\begin{proof}
	The linear forms $\varphi_i:c\longrightarrow c_i$ for $i\in \lbrace 1,\ldots, D\rbrace$ are linearly independent on $\Q^D,$ hence one can extract a subfamily $(\varphi_i)_{i\in I}$ that is a basis of the space of linear forms on the (rational) direction of $V.$

	Now, if we take a non-zero polynomial $P,$ for $P(A^{c_{i_1}},\ldots, A^{c_{i_k}})$ to vanish at some $c\in V,$ one must have that two distinct monomials of $P$ have the same degree in $A.$ If we fix two such monomials in $P,$ this amounts to an equation of the form $a_1\varphi_{i_1}(c)+\ldots + a_k\varphi_{i_k}(c)=d$ where $d$ is a constant and the $a_i$'s do not all vanish. Since the $\varphi_{i_j}$ are linearly independent on the direction of $V,$ this equation is only satisfied on a sublattice of $V$ of rank $k-1.$ Since there are only a finite number of monomials in $P,$ the lemma follows.  
\end{proof}
\begin{lemma}
	\label{lemma:lin_alg}
	Let $v_1,\ldots,v_n$ be a basis of $\Q^n,$ and let $V\subset \Q^n$ a subspace of dimension $d<n.$ Then we can pick $J\subset \lbrace 1,\ldots,n\rbrace$ such that 
	\begin{itemize}
		\item[(1)]$W=\mathrm{Span}_{j\in J}\lbrace v_j \rbrace$ is in direct sum with $V;$ 
		\item[(2)]For any $l\in \lbrace 1,\ldots,n \rbrace \setminus J,$ 
		$$D_l=V\cap \mathrm{Span}_{j\in J\cup \lbrace l \rbrace}\lbrace v_j \rbrace$$
		has dimension $1$;
		\item[(3)]One has $V=\underset{l\in \lbrace 1,\ldots,n\rbrace \setminus J}{\bigoplus}D_l.$
	\end{itemize}
\end{lemma}
\begin{proof}The family $(v_j)_{j\in J}$ may be chosen by the incomplete basis theorem: given $(e_1,\ldots,e_d)$ a basis of $V,$ one can pick vectors among $v_1,\ldots,v_n$ so that the $e_i$'s and the $v_j$'s form a basis of $\Q^n,$ which implies the first claim. 
	Now given such a choice of $J,$ one has that $\dim D_l\geq 1$ since $\dim V+\dim \mathrm{Span}_{j\in J\cup \lbrace l \rbrace}\lbrace v_j \rbrace =n+1,$ and also $\dim D_l\leq 1$ since $\dim V\cap W=0.$ So $\dim D_l=1.$

	Finally, 
	$$\underset{l\in \lbrace 1,\ldots,n\rbrace \setminus J }{\bigoplus}D_l=\underset{l\in \lbrace 1,\ldots,n\rbrace \setminus J }{\bigoplus} V\cap  \mathrm{Span}_{j\in J\cup \lbrace l \rbrace}\lbrace v_j \rbrace=V\cap \Q^n=V.$$
\end{proof}

We end this section with the following lemma, which we call the \emph{Chamber lemma}. Loosely speaking, it says that if a function defined on lattice points of a polytope satsfies one-dimensional recurrence relations in every direction, then outside of a union of codimension $\geq 1$ space, it is determined by a finite number of values. This lemma will be of use when in the next section, we find recurrence relations among the generators $\varphi_c$ of $Sk^{\overline{\lambda}}(M).$ 


\begin{lemma}\label{lemma:chamber}
	(\textit{Chamber lemma}) Let $n,d\geq 1$ be integers, let $e_1,\ldots, e_n$ be a basis of $\Z^n$ and let $V=\underset{i\in I}{\cap} \lbrace \varphi_i(x)\geq a_i \rbrace,$ where $\varphi_i:\Q^n\longrightarrow \Q$ are linear forms and $a_i\in \Q.$ Let $W$ be a $\Z$-module and $f:\Z^n \longrightarrow W$ be a set map satisfying the following condition for some integer $d\geq 1:$
	\begin{itemize}
		\item[(*)] $\forall x \in \Z^n \cap \mathring{V}, \forall l\in \lbrace 1,\ldots,n \rbrace, \forall \varepsilon\in \lbrace \pm 1 \rbrace,$ if $x+k\varepsilon e_i \in \mathring{V} \ \forall k\in \lbrace 1,\ldots,d \rbrace,$  then:
		$$f(x)\in \mathrm{Span}_{\Z}\lbrace f(x+k\varepsilon e_l) | 1\leq k \leq d \rbrace.$$
	\end{itemize}




	Then there exists a finite collection $(V_j)_{j\in J}$ of sub-vector spaces of $\Q^n$ of codimension at least one, such that
	$$\dim \mathrm{Span}_{\mathbb{Z}}\left\lbrace f(x) \ | \ x\in \Z^n\cap \left(\mathring{V} \setminus \underset{j\in J}{\cup} V_j \right) \right\rbrace \leq d^n.$$
\end{lemma}

\begin{proof}
	Let $V'\subset V$ be the subset of consisting of points that are at distance $\geq d+1$ to $\partial V$ for the infinity norm. Then $\Z^n \cap (V\setminus V')$ is a subset of a finite union of sets of the form $\lbrace x  \ | \ \varphi_i(x)=b_i \rbrace.$ Indeed, each $\varphi_i |_{\Z^n}$ take discrete values, and since any point $x$ of $V\subset V'$ is within bounded distance of $\partial V,$ one must have $|\varphi_i(x)-a_i|\leq M(d+1)$ for at least one $i\in I.$ (Here $M$ is the maximum of the norms of $\varphi_i$ subordinate to the norm $||\cdot ||_{\infty}$ in $\Q^n.$)

	We proceed to show that $\dim \mathrm{Span}_{\mathbb{Z}}\lbrace f(x) \ | \ x\in \Z^n\cap V' \rbrace \leq d^n.$ This is clear if $\Z^n\cap V'=\emptyset.$ Otherwise, pick $x\in \Z^n \cap V'.$ We claim that $\mathrm{Span}_{\mathbb{Z}}\lbrace f(x) \ | \ x\in \Z^n\cap V' \rbrace$ is spanned by the $\lbrace f(x+v_1e_1+\ldots v_n e_n) \ | 0\leq v_i \leq d-1 \rbrace.$ 

	Indeed, take $y\in \Z^n\cap V'.$ Notice that $V'$ is convex, hence the segment $[x,y]$ is entirely in $V'.$ Now, partition $\Q^n$ into cubes $x+dt+[0,d)^n,$ where $t\in \Z^n.$ We can find a sequence of cubes $C_1,\ldots ,C_k$ of the partition such that $C_1=x+[0,d)^n,$ $C_i$ and $C_{i+1}$ share a face, each $C_i$ is in $\mathring{V},$ and $[x,y] \subset \underset{1\leq i \leq k}{\cup} C_i.$ Those cubes are cubes that intersect $[x,y],$ ordered according to the first point of $[x,y]$ which they contain and, when tied, to the lexicographic order of their barycenter. 

	Now the lemma follows from the observation that if $C_i$ and $C_{i+1}$ share a face and are subsets of $\mathring{V},$ then $\mathrm{Span}_{\Z}\lbrace f(x) \ | \ x \in C_i \rbrace=\mathrm{Span}_{\Z}\lbrace f(x) \ | \ x \in C_{i+1} \rbrace,$ which is a direct consequence of condition (*).
\end{proof}

\section{The induction hypothesis and beginning of the induction proof}
\label{sec:induction1}
Let $M$ be a $3$-manifold with boundary, and $\lbrace \lambda_1,\ldots, \lambda_n \rbrace$ be a pair of pants decomposition of $\partial M.$ We also fix a Heegaard splitting $M=H\underset{\Sigma}{\cup} C,$ where $C$ is a compression body, and $H$ is a handlebody. We assume that $H$ has genus at least $2$, which can always be achieved via stabilization. Recall that $Sk(M,\Q(A))$ is spanned by the vectors $(\varphi_c)_{c \in \Delta}$ by Lemma \ref{lemma:basis}. We will show that $Sk^{\overline{\lambda}}(M)$ is a finite dimensional $\Q(A,\overline{\lambda})$ vector space by an induction. Our induction hypothesis is

\smallskip

\textbf{Induction hypothesis:} There exists a finite collection $(V_s)_{s\in S}$ of affine subspace of $\Z^{3g-3}$ of co-dimension at least $1,$ such that
$$\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c\in \Delta \setminus \underset{s\in S}{\bigcup}V_s\rbrace \ \textrm{is finite dimensional}$$

where we induct lexicographically on the $3g-3$-tuple $(n_1,n_2,\ldots,n_{3g-3}),$ where $n_i$ is the number of affine subspace $V_s$ of codimension $i.$

\smallskip

We note that once arrived at $(n_1,\ldots,n_{3g-3})=(0,\ldots,0,k)$ for some $k\in \N,$ the finiteness theorem is proved, since subspaces of codimension $3g-3$ are just points. First we need to prove that some finite collection $(V_s)_{s\in S}$ exists.

\begin{proof}[Proof of the base case]
	For each $i\in \lbrace 1,\ldots, 3g-3 \rbrace,$ consider the family of curves $\lbrace \alpha_1,\ldots,\alpha_{3g-3},\beta_i \rbrace.$ By Lemma \ref{lem:linDep}, there is $P_i\neq 0$ in $\Q(A,\overline{\lambda})[x_1,\ldots,x_{3g-2}],$ such that $P_i(\alpha_1,\ldots,\alpha_{3g-3},\beta_i)=0$ in $Sk^{\overline{\lambda}}(C),$ where $C$ is the compression body in the Heegaard splitting of $M.$

	Therefore, we have 
	$$\forall c\in \Delta,  P_i(\alpha_1,\ldots,\alpha_{3g-3},\beta_i)\cdot \varphi_c =0 $$
	in $Sk^{\overline{\lambda}}(M).$

	Let $d_i$ be the degree of $P_i$ in $\beta_i.$
	By Lemmas \ref{lem:linDep} and \ref{lemma:curveActions}, for $c\in \Delta \setminus N(\partial \Delta),$ we have recurrence relations among the $\varphi_c \in Sk^{\overline{\lambda}}(M)$ of the form:

	$$R_{-2d_i}(A,A^{c_1},\ldots,A^{c_{3g-3}})\varphi_{c-2d_i\delta_i} + \ldots + R_{2d_i}(A,A^{c_1},\ldots,A^{c_{3g-3}})\varphi_{c+2d_i\delta_i}=0.$$

	In the above, the $(R_{i})_{-2d \leq i \leq 2d}$ are polynomials in $3g-2$ variables, with $R_{2d}$ and $R_{-2d}$ non-zero. Moreover, $\delta_i$ is the vector of $\Z^{3g-3}$ whose only non-zero coordinate is the $i$-th coordinate, which is $1.$ Also $N(\partial \Delta)$ designates a neighborhood of the boundary of $\Delta,$ that is, a finite union of translates of its facets.

	By Lemma \ref{lemma:non-vanishing_poly}, the coefficients $R_{-2d}(A,A^{c_1},\ldots,A^{c_{3g-3}})$ and $R_{2d}(A,A^{c_1},\ldots,A^{c_{3g-3}})$ are both non-zero on the complement in $\Z^{3g-3}$ of a finite union of codimension $\geq 1$ subspaces.

	Varying $i\in \lbrace 1,\ldots, 3g-3 \rbrace,$ we get that the $\varphi_c$ satisfy one-dimensional recurrence relations with invertible dominant coefficients in all directions, except when $c$ belongs to some finite union of codimension $\geq 1$ subspaces of $\Delta.$ The complement of this finite union is a finite union of chambers of $\Z^{3g-3}$ such that the map $c\longrightarrow \varphi_c$ satisfies the condition (*) of Lemma \ref{lemma:chamber}, for $d=max(4d_i).$

	Lemma \ref{lemma:chamber} can now be applied and gives that there exists a finite collection $(V_s)_{s\in S}$ of codimension $\geq 1$ subspaces of $\Z^{3g-3},$ such that 
	$$\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c\in \Delta \setminus \underset{s\in S}{\bigcup}V_s\rbrace \ \textrm{is finite dimensional}$$ 
\end{proof}

Having proved the base case, we move on to proving the induction step. We divide the proof in two cases: 
\begin{itemize}
	\item[Case 1:] The collection $(V_i)_{i\in I}$ contains a subspace which is not contained in a translate of a facet of $\Delta.$
	\item[Case 2:] There is no such subspace.
\end{itemize} 
While the method of proof for the latter case applies also to the former, it is considerably more complicated. Hence for the clarity of exposition we will start by exposing the argument for the induction step in Case 1.


\begin{proof}[Proof of Induction step in Case 1]
	In all what follows, we set $n=3g-3.$

	Let $V_0$ be an element of our finite collection $(V_s)_{s\in S}$ of affine subspaces of $\Z^{3g-3},$ which is not contained in a translate of any facet of $\Delta,$ and which is of maximal dimension among those. Let $k=\dim V_0.$ First we choose a subset $J$ of cardinality $n-k$ of the canonical basis $\lbrace e_1,\ldots,e_n \rbrace$ of $\Z^n$ as in Lemma \ref{lemma:lin_alg}. There may be parallel copies of $V_0$ in the collection $(V_s)_{s\in S}.$ In that case, the parallel copies of $V_0$ must be of the form $V_0+x_{j_1}e_{j_1}+\ldots + x_{n-k}e_{j_{n-k}},$ where the $x_j$'s are in $\Z.$ We will now redefine $V_0$ to be a parallel copy $V_0+x_{j_1}e_{j_1}+\ldots + x_{n-k}e_{j_{n-k}},$ where $(x_{j_1},\ldots,x_{j_{n-k}})$ is maximal for the lexicographical ordering.

	We pick another subset $I\subset \lbrace 1,\ldots,n \rbrace$ according to Lemma \ref{lemma:non-vanishing_poly}. Now for any $l \in \lbrace 1,\ldots n \rbrace \setminus J,$ consider the family of curves 
	$$F_l=\lbrace \alpha_i\rbrace_{i\in I} \cup \lbrace \beta_j \rbrace_{j\in J \cup \lbrace l \rbrace}.$$
	The family $F_l$ contains $n+1=3g-2$ elements, hence we can apply Lemma \ref{lem:linDep} to get a non-zero polynomial $P_l$ such that
	$$P_l(\alpha_i,\beta_j,\beta_l)=0 \in Sk^{\overline{\lambda}}(C),$$
	and therefore $P_l(\alpha_i,\beta_j,\beta_l)\cdot \varphi_c=0$ in $Sk^{\overline{\lambda}}(M),$ for any $c\in \Delta.$

	Let $D_l$ be the total degree of $P_l$ in the variables $\beta_j,\beta_l.$ We consider $U\subset V_0,$ which is the subset of $V_0$ consisting of elements that are at distance at least $4D_l$ to any facet of $\partial \Delta$ and to any other subspace $V_s$ where $s\in S$ which is not parallel to $V_0.$ Since all the subspaces considered are non-parallel to $V_0,$ the set $U$ is the complement in $V_0$ of a finite union of subspaces of $V_0$ of codimension at least $1.$  

	With this setup, we have:

	\medskip

	\textbf{Claim:} For any $l\in \lbrace 1,\ldots,n \rbrace \setminus J$ and $c\in U,$ we have a recurrence relation for the $\varphi_c$ of the form 

	$$ R_{d_l}(A,A^{c_{i_1}},\ldots , A^{c_{i_k}})\varphi_{c+d_l u_l} + \ldots + R_{-d_l}(A,A^{c_{i_1}},\ldots , A^{c_{i_k}})\varphi_{c-d_l u_l} \equiv 0,$$
	where the vector $u_l$ is a generator of the line $D_l$ given in Lemma \ref{lemma:lin_alg}, $d_l$ is an integer, $R_{\pm d_l}$ are non-zero polynomial in $k+1$ variables, and $\equiv$ is equality up to an element of 
	$$E_0=\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c \in \Delta \setminus \underset{s\in S}{\bigcup} V_s \rbrace.$$

	\begin{proof}[Proof of the Claim] Consider $N(P_l),$ the Newton polygon of the polynomial $P_l$ in terms of the variables $\beta_j,\beta_l,$ which we define to be the convex hull of the elements $\underset{j\in J \cup \lbrace l \rbrace}{\sum}2\varepsilon_j n_j \delta_j,$ ranging over all $n+1-k$-uples $(n_j)_{j\in J\cup \lbrace l \rbrace}$ such that $\underset{j\in J\cup \lbrace l \rbrace}{\prod}\beta_j^{n_j}$ is a monomial in $P_l$ with non-zero coefficient. Then, for any $c$ such that $c+N(P_l)\subset \Delta,$ we have

		\begin{equation} \label{eq:rec_rel-Case1}P_l(\alpha_i,\beta_j ,\beta_l)\cdot \varphi_c= \underset{x\in N(P_l)}{\sum }R_x(A,A^{c_{i_1}},\ldots A^{c_{i_k}})\varphi_{c+x}.\end{equation}

		where the $R_x$ are rational fractions with non-vanishing denominators at $c$, and furthermore $R_x$ is a non-zero if $x$ is a vertex of $N(P_l).$

		However, thanks to Lemma \ref{lemma:lin_alg}, there is $v\in \Z^n$ such that $c+v+N(P_l)$ intersects $V_0$ only in an affine line parallel to $D_l,$ and intersects no subspace $V_s\neq V_0$ which is  parallel to $V_0.$ Indeed, pick $v=y_{j_1}e_{j_1}+\ldots y_{j_{n-k}}e_{j_{n-k}}$ with $y$ maximal for the lexicographical order such that $V_0$ and $c+v+N(P_l)$ intersect; then $c+v+N(P_l)$ does not intersect other $V_s$ parallel to $V_0$ by maximality, and it intersects $V_0$ in a point or in a line parallel to $D_l,$ by construction of the set $J.$ We can further add to $v$ an element of the direction of $V_0$ to recenter this line. In the end, applying Equation \ref{eq:rec_rel-Case1} to $c'=c+v,$ we get the claim, since all other elements of $c+v+N(P_l)$ are in $E_0,$ by construction of $U.$
	\end{proof}

	Given the claim, we conclude similarly to the proof of the base case: there is a finite collection of codimension $\geq 1$ subspaces in $V_0$ such that all polynomials $R_{\pm d_l}$ are non-vanishing on the complement, and those subspaces divide $U$ into a finite collection of chambers to which we can apply Lemma \ref{lemma:chamber}. 

	Note that since the recurrence relations involved the relation $\equiv$ instead of equality, what we get from this is the following. There is a finite collection $(W_t)_{t\in T}$ of codimension $\geq 1$ subspaces in $V_0,$ such that, writing 
	$$E_1=\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace\varphi_c \ | \ c \in V_0 \setminus \underset{t\in T}{\bigcup} W_t \rbrace$$
	and 
	$$E_0=E_1 \cap \mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c \in \Delta \setminus \underset{s\in S}{\bigcup} V_s \rbrace,$$ 
	then we have
	$$\dim E_1/E_0 <+\infty.$$

	However, $\dim E_0<+\infty$ by induction hypothesis, hence $\dim E_1<+\infty.$ 

	Therefore, we can replace in the finite collection $(V_s)_{s\in S},$ the subspace $V_0$ by the finite collection $(W_t)_{t\in T},$ which contains only subspaces of higher codimension than $V_0.$ Therefore we have completed the induction step in Case 1. 
\end{proof}

The proof of the inductive step in Case 2, which is significantly more involved, will be completed in Section \ref{sec:finalproof}, after we construct a set of operators to replace the $\beta_i$s in the proof of Case 1.


\section{The boundary of polytope of admissible colorings}
\label{sec:polytope-boundary}
\subsection{Notation and basic definitions}


\begin{definition}\label{def:nearadmissible}
	Let $\Gamma$ be a lollipop tree. Take some edges $e_1,\dots,e_l$, some directed vertices $(v_{l+1},e_{l+1}),\dots,(v_{k},e_k)$ and natural numbers $a_1,\dots,a_k$. 

	Then the \emph{barely admissible subspace} of $\Delta$ associated to these choices is the subset $V\subseteq \Delta$ defined by the equations
	$d(e_i)=a_i$ for $1\leq i\leq l$, and $d(v_{j},e_{j})=a_j$ for $l+1\leq j\leq k$.

	We say that a subset $V\subseteq \Delta$ is barely admissible if it is the barely admissible subspace associated to some choice.

\end{definition}

\begin{remark}
	A barely admissible subspace is not, technically speaking, a subspace; it is rather a subspace of $\Z^\mathcal{E}$ intersected with $\Delta$. With a slight abuse of notation, we will talk about dimension, codimension or a basis for a barely admissible subspace $V$; we will always mean dimension, codimension or basis for the unique subspace of $\Z^\mathcal{E}$ whose intersection with $\Delta$ gives $V$.
\end{remark}

In what follows, when we write $d(x)$ we mean that $x$ is either an edge or a directed vertex. If we wish to specify that $x$ is an edge we will use the letter $e$ instead. 

\begin{definition}\label{def:simpleNAS}
	Let $V$ be a barely admissible subspace characterized by the equations $\{d(x_i)=a_i\}$ for $i=1,\dots,k$. Then $F$ is \emph{simple} if the following conditions hold:
	\begin{itemize}
		\item if $x_i=e_i$ and $x_j=e_j$ then $e_i=e_j$ implies $i=j$;
		\item if $x_i=(v_i,e_i)$ and $x_j=(v_j,e_j)$, $v_i=v_j$ implies $i=j$;
		\item if $v$ is a vertex of $\Gamma$ that does not appear among the $x_i$'s, then either all edges adjacent to $v$ appear among the $x_i$'s or none of them do;
		\item if $x_i=(v_i,e_i)$ and two of the edges adjacent to $v$ coincide, they must not be $e_i$;
		\item if $x_i=(v,e)$, then $e$ does not also appear as an edge among the $x_i$s;
		\item if $x_i=(v,e)$, then at most one edge adjacent to $v$ appears as an edge among the $x_i$s;
		\item if $x_i=(v,e)$ and a loop edge is adjacent to $v$, it must not appear among the $x_i$s.
	\end{itemize}
\end{definition}
\begin{lemma}\label{lemma:unionsimpleNAS}
	A non-empty barely admissible subspace $V$ is a finite union of simple barely admissible subspaces.
\end{lemma}
\begin{proof}
	Call $x_i$ and $a_i$ the choices used to define $V$. Notice that if $x_i=x_j=e_i$ then either $V$ is empty or one equation is redundant, hence can be tossed out.

	Suppose that there are $i\neq j$ such that $v_i=v_j$; if $e_i=e_j$ and $a_i=a_j$ then the equation is redundant and can be tossed out, whereas if $a_i\neq a_j$ then $V$ is empty. So suppose that $e_i\neq e_j$. Then two of the equations characterizing $V$ are $d(e_k)+d(e_j)-d(e_i)=a_i$ and $d(e_k)+d(e_i)-d(e_j)=a_j$, where $e_k$ is the third edge adjacent to $v_i$. Summing these two equations together we find that $2d(e_k)=a_i+a_j$, which implies either $V$ empty (if $a_i+a_j$ is odd) or $d(e_k)=(a_i+a_j)/2$. Therefore we can toss out one among $x_i,x_j$ and substitute it (without changing $V$) with $e_k$ and $a_k:=(a_i+a_j)/2$. Repeat this process until the choices for $V$ satisfy the second condition of simplicity.

	Now suppose that $v$ does not appear as a vertex among the $x_i$'s, and call $e_1,e_2,e_3$ the edges adjacent to $v$. Suppose that $e_1$ appears among the $x_i$'s and the other two do not. Then the triangular inequalities defining $\Delta$ say that $d(e_2)+a_1-d(e_3)\geq 0$ and $d(e_3)+a_1-d(e_2)\geq 0$, which implies in particular that $d(e_2)-d(e_3)\leq a_1$. Therefore we can add to the equations defining $V$ the inequality $0\leq d(e_2)+d(e_1)-d(e_3)\leq 2a_1$ without changing $V$. Therefore $V=V_1\sqcup \dots V_{a_1}$ where $V_k$ is defined by the same equations as $V$ plus the additional equation $d(v,e_3)=2k$.

	Now take $v$ any vertex, call as before $e_1,e_2,e_3$ the adjacent edges and suppose that $e_1$ and $e_2$ appear among the $x_i$'s and $e_3$ does not. Then the triangular inequalities at $v$ imply that $e_3$ must be at most $a_1+a_2$, therefore we can decompose $V$ into subspaces where $e_3$ appears among the $x_i$'s.

	Suppose that $x_i=(v_i,e_i)$ and $e_i$ coincides with another edge adjacent to $v_i$; then the equation given by $x_i$ reduces to $d(e)=a_i$, where $e$ is the remaining edge; thus we can replace $x_i$ with $e$.

	Now suppose that $v$ appears as a vertex among the $x_i$'s, with chosen edge $e$, and suppose that $e$ appears among the $x_i$'s. Then in $V$ we have $d(v,e)=a$ and $d(e)=b$, which implies that $d(e_1)+d(e_2)= a+b$, and since both $d(e_1)$ and $d(e_2)$ are non-negative, $V$ is contained in a finite union of barely admissible subspaces where $e_1$ and $e_2$ are both among the $x_i$'s. 

	Finally suppose that $v$ appears as a vertex among the  $x_i$'s, with chosen edge $e$, and both of the other edges adjacent to $v$ appear among the $x_i$'s. Then this determines the value of $e$ in $V$, hence we can replace $v$ with $e$ without changing $V$. This also applies if a loop edge adjacent to $v$ appears among the $x_i$s.
\end{proof}

\subsection{The singular and flow subgraphs}

\begin{figure}
	\includegraphics[scale=0.3]{figures/directedvertex}
	\caption{The direction of half edges around a vertex of $\Phi_V$; the upwards edge is the one appearing with a negative sign in the defining equations of $V$}
	\label{fig:directededge}
\end{figure}
\begin{definition}\label{def:subgraphs}
	If $V$ is a simple barely admissible subspace characterized by the equations $\{d(x_i)=a_i\}$, we can associate to it two subgraphs of $\Gamma$, the singular subgraph $\Gamma_V$ and the flow subgraph $\Phi_V$.

	The \emph{singular subgraph} is defined as the union of all edges appearing among the $x_i$'s; we will draw it with dashed edges.

	The \emph{flow subgraph} $\Phi_V$ is defined as the closure of the union of the non-singular edges adjacent to each vertex appearing among the $x_i$'s; the signs of each adjacent edge of $v$ gives an orientation on the half edges adjacent to $v$ as in Figure \ref{fig:directededge}. This makes $\Phi_V$ into a bidirected graph; we draw it depicting the orientations.

	Denote with $R_V$ the closure of the complement of $\Gamma_V\cup\Phi_V$ in $\Gamma$, and call it the regular subgraph of $V$.

\end{definition}


We can define a partial order on the vertices of the flow subgraph; we say that $v_1\succ v_2$ if there is a directed path from $v_1$ to $v_2$, and extend it to a total order on the $x_i$'s (so that all the vertices appear after the edges); call this order $\succ$.


\begin{lemma}\label{lemma:codimension}
	If $V$ is a simple barely admissible subspace characterized by the equations $\{d(x_i)=a_i\}$ for $i=1,\dots,k$, then its codimension is $k$.
\end{lemma}
\begin{proof}
	Since $V$ is realized as an intersection of affine hyperplanes, we need only to show that the dual vectors $x_i$ to the supporting hyperplanes are linearly independent in $\Z^\mathcal{E}$. These vectors are of the form $e_i$ (if the hyperplane is of the form $d(e_i)=a_i$) or $e_i+e_j-e_k$ (if the hyperplane is of the form $d(v_i,e_k)=a_i$). Suppose that $\lambda:=\sum_i\lambda_i x_i=0$; if we show that in any such sum, there is one edge $e$ with non-zero coefficient which only appears once, we have our desired result (since the edges themselves are linearly independent).

	To see this, first consider $\Phi'$ the subgraph of the flow subgraph $\Phi_V$ spanned by the vertices with non-zero coefficient in $\lambda$. If this is non-empty, take $e$ a leaf of $\Phi'$; it cannot be a dashed edge (since they are not part of $\Phi_V$) hence it can only appear in $\lambda$ once.

	Suppose instead that $\Phi'$ is empty; then any edge in $\lambda$ corresponds to an edge of the singular subgraph and thus can only appear once in $\lambda$.

\end{proof}


From now on, we fix $V$ a codimension $k$ simple barely admissible subspace of $\Delta$; we call $x_1,\dots,x_k$ the choices of edge or directed vertex defining $V$, ordered according to $\succ$. We also call $f:\Z^\mathcal{E} \ra\Z^{k}$ the function given by $f(d)=(d(x_1),\dots,d(x_k))$. We consider $\Z^k$ to be ordered under the lexicographic order induced by $\succ$. 

Consider the set $\mathcal{E}'$ given by:

\begin{itemize}
	\item The regular edges of $\Gamma$;
	\item the introverted edges of $\Phi_V$;
	\item the leaves of $\Phi_V$.
\end{itemize}

Notice that the cardinality of $\mathcal{E}'$ is larger than $\textrm{dim}(V)$; more precisely the dimension of $V$ is equal to the cardinality of $\mathcal{E}'$ minus the number of extraverted edges of $\Phi_V$ (this will be proved in Lemma \ref{lemma:basisV}).

We define the \emph{orthogonal map} as the map $g:\Z^\mathcal{E}\ra \Z^{\mathcal{E}'}$ given by $g(\delta_e)=\delta_e$ if $e$ is an introvorted edge of $\Phi_V$, a non-loop leaf of $\Phi_V$, or a regular edge, $g(\delta_e)=2\delta_e$ if $e$ is a loop edge of $\Phi_V$ and $0$ otherwise.


Finally we fix an additional ordering $\succ'$ that we will use to select certain edges later. Suppose $e_1,\dots,e_l$ are a maximal collection of introverted edges of $\Phi_V$ such that $e_i\cap e_{i+1}=v_i$; then we say that $e_i\succ'e_j$ if $i<j$. Notice that since there are no cycles in $\Phi_V$ this gives a total order on the $e_i$s. Extend this order arbitrarily to an order, still denoted $\succ'$, of all regular edges of $\Gamma$, introverted edges and leaves of $\Phi_V$.



\subsection{Operators adapted to barely admissible subspaces}
\label{sec:curvop-nearadm}
In this subsection we build some operators that, in some sense, behave well with respect to a given barely admissible subspace; we will use them to, roughly speaking, push a color in $V$ further into $\Delta$. We build these operators from the singular and flow subgraphs of $\Gamma$, using the curve operators of Lemmas \ref{lemma:curveActions} and \ref{lemma:longcurveactions}. We first start with a very basic lemma about curve operators.

\begin{lemma}\label{lemma:minshiftdashed}
	Let $e\subseteq \Gamma_V$ be a dashed edge; then the operator $T^{\beta_e}$ has a unique minimal shift given by $-\delta_e$ if $e$ is a loop edge, and $-2\delta_e$ otherwise. 
\end{lemma}
\begin{proof}
	By Lemma \ref{lemma:curveActions}, the shifts in $T^{\beta_e}$ are $0$ and $\pm 2\delta_e$, and $f(\delta_e)=\delta_e$, therefore the unique minimal shift of $T^{\beta_e}$ is $-2\delta_e$.
\end{proof}

The problem of using the operator $T^{\beta_e}$ for our purposes is that, if $\Gamma_V$ contains connected components of more than one edge, there will be no admissible color $c$ such that $\varphi_{c-2\delta_{e}}\in V$, or in other words, no element of $V$ is effective for $T^{\beta_e}$. Therefore we need to use more complicated operators that are adapted to $V$.

\begin{definition}\label{dfn:pathop}
	Consider a path $\gamma\subseteq \Gamma$. We define the \emph{path operator} $T^{\gamma}$ as $$T^{\gamma}:=T^{\beta_{\mathring{\gamma}}}T^{\beta_{\partial\gamma}}.$$
\end{definition}

The next lemmas act as a definition of the operators we are looking for; the proofs are all very similar so we will carry out in detail the first, and then simply point out the subtle differences for the others.

\begin{lemma}\label{lemma:extopfirst}
	Let $\gamma\subseteq \Gamma_V$ be a maximal arc, and consider the path operator $T^{\gamma}:\Sk(H)\ra\Sk(H)$.

	Then:
	\begin{itemize}
		\item $T^\gamma$ has a unique minimal shift $x$;
		\item $f(x)(e)=-1$ if $e$ is a loop edge of $\gamma$, $f(x)(e)=-2$ if $e$ belongs to $\mathring{\gamma}$, $f(x)(v)=-2$ if $v$ is an endpoint of $\gamma$, $f(x)(y)=0$ otherwise and $g(x)=0$.
		\item there is a finite union of barely admissible subspaces $W\subseteq V$, each of codimension $1$, such that for all $y\in V\setminus W$, $y$ is effective for $T^\gamma$ and $y-x\in \Delta\setminus V$.
	\end{itemize}
\end{lemma}

\begin{proof} By Lemmas \ref{lemma:longcurveactions} and \ref{lemma:uniqueminimalshift}, $T^{\gamma}$ has a unique minimal shift given by $x=-\sum_{e \textrm{ in }\partial\gamma} \delta_e-2\sum_{e \textrm{ in }\mathring{\gamma}} \delta_e$. The values of $f(x)$ and $g(x)$ follow at once. We need to prove the last property.

	Take $y\in V$; we know that clearly $y-x\notin V$, therefore we want to show that $y-x\in \Delta$ unless $y$ belongs to $W$, where $W$ is some union of codimension $1$ barely admissible subspaces, i.e. the color $y-x$ satisfies the triangular inequalities (since the non-negative and evenness conditions are automatic, as $x$ has negative entries which are even on non-loop edges). Consider the triangular inequalities corresponding to a vertex $v$. If $\gamma$ does not contain $v$, then clearly if $y$ satisfies the triangular inequality at $v$ then so does $y-x$. If $\gamma$ contains $v$ in its interior, then the same holds. Indeed, if $v$ is not adjacent to a loop edge, $-x$ is adding $2$ to two edges out of three adjacent to $v$; this means that either $2$ is added to both sides of the inequality, or $4$ is added to the larger side. If $v$ is adjacent to a loop edge then $2$ is added to both sides of the inequality. Finally, if $v$ is an endpoint of $\gamma$, then $-x$ is adding $2$ to one side of the inequality; the only case to consider is if it is adding it to the smaller side. If $y$ is such that $y(e_i)+y(e_j)\geq y(e_l)$ but $y(e_i)+y(e_j)\ngeq y(e_l)+2$, then it means that $y(e_i)+y(e_j)=y(e_l)$ and therefore $y$ belongs to the subspace of $V$ given by this extra equation (notice that the subspace is proper because of the simplicity assumption). Repeating this reasoning for the other endpoint (if any) of $\gamma$ shows that if $x$ does not belong to the union of these two barely admissible subspaces, $y-x\in \Delta$. The fact that $y$ is effective for $T^\gamma$ follows from Lemma \ref{lemma:longcurveactions} and Corollary \ref{cor:effectiveness}.
\end{proof}

\begin{lemma}\label{lemma:extopsecond}
	Let $v\in\Phi_V$ be a vertex and $\gamma_v$ be a maximal directed path starting from $v$. Notice that the final edge of $\gamma_v$ is either a leaf of $\Phi_V$ or an introverted edge. Define the path operator
	$T^{v}:=T^{\gamma_v}$.
	Then

	\begin{itemize}
		\item $T^{v}$ has a unique minimal shift $x$;
		\item $f(x)(w)=-2$ if $w$ is an endpoint of $\gamma_v$ in $\Phi_V$,  $f(x)(v')=0$ if $v'$ is not, and $f(x)(e)=0$;
		\item $g(x)(e)=-2$ if $e$ is the final edge of $\gamma_v$, $0$ otherwise.
		\item there is a union of barely admissible subspaces $W\subseteq V$, each of codimension $1$, such that for all $y\in V\setminus W$, $y$ is effective for $T^\gamma$ and $y-x\in \Delta\setminus V$.
	\end{itemize}
\end{lemma}
\begin{proof}
	The fact that $T^{v}$ has a unique minimal shift equal to $$x=-\sum_{e \textrm{ edge of }\partial\gamma_v}\delta_e-2\sum_{e \textrm{ edge of }\mathring{\gamma}_v} \delta_e$$ is a consequence of Lemmas \ref{lemma:curveActions} and \ref{lemma:uniqueminimalshift}. This means that if $w$ is an endpoint of $\gamma_v$, $w$ has only one adjacent edge in the sum, thus $f(x)(w)=-2$. For every other vertex $v'\in \Phi_V$, either $v'\notin \gamma_v$, or exactly two edges in $\gamma_v$ are adjacent to $v'$ and they appear with opposite signs, or $v'$ is in $\gamma_v$ and adjacent to a loop edge; in all cases $f(x)(v')=0$. The other calculations about $f$ and $g$ are obvious.

	The proof of the last part of the result follows from the same line of reasoning as Lemma \ref{lemma:extopfirst}.

\end{proof}

\begin{lemma}\label{lemma:intopfirst}
	Let $e\subseteq R_V$ be a regular edge, and define $T^e:=\left(T^{\beta_e}\right)^2$ if $e$ is a loop edge, and $T^e:=T^{\beta_e}$ otherwise. Then 

	\begin{itemize}
		\item $T^e$ has two different non-zero minimal shifts $2\delta_e$ and $-2\delta_e$;
		\item there is a union of barely admissible subspaces $W\subseteq V$, each of codimension $1$, such that for all $y\in V\setminus W$ and any $x$ minimal shifts of $T^e$, $y$ is effective for $T^e$ and $y-x\in V$.
	\end{itemize}
\end{lemma}
\begin{proof}
	The first part of this Lemma is simply noting that the three shifts of $T^e$ given by Lemma \ref{lemma:curveActions} are all in the kernel of $f$. The second part is proved exactly the same way as Lemma \ref{lemma:extopfirst}.
\end{proof}
\begin{remark}
	The only reason for the square in the definition of $T^e$ is to simplify notation in later lemmas.
\end{remark}

\begin{lemma}\label{lemma:intopsecond}
	Let $e$ be a leaf of $\Phi_V$ and $\gamma_e\subseteq \Phi_V$ be the maximal directed path ending in $e$, and define the path operator $T^{\gamma_e}$. Then 

	\begin{itemize}
		\item $T^{\gamma_e}$ has a unique minimal shift $x$;
		\item if the first edge of $\gamma_e$ is directed, $f(x)=-4\delta_v$ where $v$ is the second vertex of $\gamma_e$;
		\item if the first edge of $\gamma_e$ is extraverted, $f(x)=-4(\delta_v+\delta_{v'})$, where $v,v'$ are the endpoints of the extraverted edge.
		\item $g(x)=-2\delta_e$;
		\item there is a union of barely admissible subspaces $W\subseteq V$, each of codimension $1$, such that for all $y\in V\setminus W$, $y$ is effective for $T^\gamma$ and $y-x\in \Delta$.
	\end{itemize}
\end{lemma}
\begin{proof}
	The fact that $T^{\gamma}$ has a unique minimal shift works exactly the same way as before. We assume for simplicity that $\gamma$ contains no loop edges; the other case is identical. By Lemma \ref{lemma:longcurveactions}, the shifts of $T^{\gamma}$ are $$\sum_{e \textrm{ edge of }\gamma}\pm 2\delta_{e}.$$

	Number the internal vertices of $\gamma$ as $v_1\succ v_2 \succ \dots \succ v_r$, and number the edges of $\gamma$ as $e_0,\dots,e_r$ in the same order. If the first edge of $\gamma$ is an extraverted edge, then $\gamma$ has as endpoint an additional $v_0$ in the interior of $\Phi_V$; in this case $v_0$ might be larger than $v_1$ but either way the proof proceeds the same way.

	Suppose first that either $v_1\succ v_0$ or $v_0$ does not exist. Then to find the minimal shift $x$ we need to first minimize $f(x)(v_1)$ which is achieved by choosing the $+$ sign on $e_0$ and the negative sign on $e_1$. Among these shifts, we then need to minimize $f(x)(v_2)$, which is achieved by choosing the $-$ sign on $e_3$, and so on until we find that the minimal shift must be $2\delta_{e_0}-2\sum_{i=1}^r\delta_{e_i}$.

	If instead $v_0\succ v_1$, we first must minimize $f(x)(v_0)$ which is achieved by choosing the $+$ sign on $e_0$ anyways, which means that the rest of the argument goes exactly the same and the conclusion is the same.

	The calculations of the values of $f$ and $g$ are straightforward.

	The proof for the last bullet point is exactly the same as the one for Lemma \ref{lemma:extopfirst}; notice that in this case, even though the minimal shift of $T^{\mathring{\gamma}}$ has some positive coefficients, the minimal shift of $T^{\partial\gamma}$ is non-positive, and that is all we need to apply Corollary \ref{cor:effectiveness}.
\end{proof}

The next lemma is simply a variation of Lemma \ref{lemma:intopsecond} and is proven in the exact same way.
\begin{lemma}\label{lemma:intopsecondintro}
	Let $e$ be an introverted edge of $\Phi_V$, $\gamma_e\subseteq \Phi_V$ be a maximal directed path ending in $e$, and define the path operator $T^{\gamma_e}$. Then 

	\begin{itemize}
		\item $T^{\gamma_e}$ has a unique minimal shift $x$;
		\item if the first edge of $\gamma_e$ is directed, $f(x)=-4\delta_v-2\delta_{w}$ where $v$ is the second vertex of $\gamma_e$ and $w$ is the endpoint of $\gamma_e$ on the introverted edge;
		\item if the first edge of $\gamma_e$ is extraverted, $f(x)=-4(\delta_v+\delta_{v'})-2\delta_w$, where $v,v'$ are the endpoints of the extraverted edge and $w$ is the endpoint of $\gamma_e$ on the introverted edge.
		\item $g(x)=-2\delta_e$;
		\item there is a union of barely admissible subspaces $W\subseteq V$, each of codimension $1$, such that for all $y\in V\setminus W$, $y$ is effective for $T^\gamma$ and $y-x\in \Delta$.
	\end{itemize}
\end{lemma}


\section{Witten's finiteness conjecture}
\label{sec:finalproof}



\subsection{External and internal operators of $V$}

We now proceed to define a set of operators that will allow us to perform the inductive step in the proof. 


\begin{definition}\label{def:extopfirst}
	Take a connected component of $\mathring{\Gamma}_V$, take a planar projection of it and choose one if its leaves $e$ as a root. Notice that if this connected component contains $2n+1$ edges, then it contains $n+2$ leaves. Take $\gamma_1,\dots,\gamma_{n+1}$ maximal arcs each connecting $e$ to one of the other leaves, and also take $\gamma_{n+2},\dots,\gamma_{2n+1}$ maximal arcs connecting two adjacent leaves (different from $e$) in the chosen projection. Append to each $\gamma_i$ any edge loop in $\Gamma_V$ that it touches. Repeat this process for each connected component of $\Gamma_V$ to obtain $\gamma_1,\dots,\gamma_l$ where $l$ is the number of edges of $\mathring{\Gamma}_V$, and take $T^{e_{l+1}},\dots,T^{e_{r}}$ where $e_k$ is an edge loop of $\Gamma_V$. We call $T^{\gamma_1},\dots,T^{\gamma_l},T^{e_{l+1}},\dots,T^{e_r}$ the \emph{external operators of the first kind} for $V$.
\end{definition}
\begin{lemma}\label{lemma:exttopfirstindep}
 The external operators of the first kind have unique minimal shifts $x_1,\dots,x_r$ and $f(x_1),\dots,f(x_r)$ are linearly independent.
\end{lemma}
\begin{proof}
	The uniqueness of the minimal shifts is from Lemma \ref{lemma:extopfirst}; we only need to show that $f(x_1),\dots,f(x_r)$ are linearly independent. To do this, we show by induction on $r$ that the span over $\Q$ of $f(x_1),\dots,f(x_r)$ is equal to the span of $\delta_{e_1},\dots,\delta_{e_r}$, where $e_1,\dots,e_r$ are the edges of $\Gamma_V$. If there are edge loops in $\Gamma_V$, then some of the $f(x_i)$'s are equal to $\delta_{e_i}$; we can simply remove them from any $f(x_j)$ where they appear without affecting the validity of the statement. Therefore we can assume that there are no edge loops. We now proceed by induction on $r$.

	\begin{figure}
		\includegraphics[scale=0.4]{figures/extoperators.pdf}
		\label{fig:extoperators}
		\caption{The three paths touching $e_1$ and $e_2$.}
	\end{figure}

	If $r=1$ there is nothing to prove. Suppose $r>1$ (which also means $r>2$ by the simplicity assumptions) and take $e_1,e_2$ (both different from the root $e$) two leaves of $\Gamma_V$ sharing a vertex. There are exactly three $\gamma_i$'s touching either $e_1$ or $e_2$, depicted in Figure \ref{fig:extoperators}; the two arcs, say (without loss of generality) $\gamma_{r-2},\gamma_{r-1}$, connecting $e_1,e_2$ respectively to $e$ and the arc connecting the two of them (which is simply $\gamma_r:=e_1\cup e_2$). Then we can obtain $4\delta_{e_1}:= x_{r-2}-x_{r-1}+x_r$ and $4\delta_{e_2}:= x_{r-1}-x_{r-2}+x_r$. This means that the span of $f(x_1),\dots,f(x_r)$ is equal to the span of $f(x_1),\dots,f(x_{r-3}),f(x_{r-2})-2\delta_{e_1},\delta_{e_1},\delta_{e_2}$. The first $r-2$ vectors of this list are the minimal shifts of the external operators associated to the singular graph obtained by removing $e_1,e_2$ from $\Gamma_V$, thus we can apply the inductive hypothesis and obtain the lemma.
\end{proof}


\begin{definition}\label{def:extopsecond}
Fix a planar embedding of $\Phi_V$. 
For any vertex $v$ of $\Phi_V$, we define a path $\gamma_v$ recursively as follows.
\begin{itemize}
	\item 
	If both outgoing edges of $v$ are leaves, define $\gamma_v$ as the leftmost edge of $v$;
	\item 
	If both outgoing edges of $v$ are introverted edges, define $\gamma_v$ as the larger outgoing edge;
	\item if one outgoing edge of $v$ is a leaf and the other is introverted, define $\gamma_v$ as the leaf;
	\item if at least one outgoing edge of $v$ is directed, choose $w$ the other endpoint of the leftmost outgoing edge and define $\gamma_v:=\gamma_w\cup \overrightarrow{vw}$.
\end{itemize}

\begin{figure}
	\includegraphics[width=0.5\textwidth]{figures/externalpaths}
	\label{fig:externalpaths}
	\caption{The paths $\gamma_{v_i}$ in Definition \ref{def:extopsecond}; notice that they always turn left except to avoid introverted edges.}
\end{figure}

Some examples are depicted in Figure \ref{fig:externalpaths}

 Let $v_1\succ \dots\succ v_n$ be the vertices of $\Phi_V$;  and define $T^{v_i}=T^{\gamma_{v_i}}$ as in Lemma \ref{lemma:extopsecond}. We call $T^{v_1},\dots,T^{v_n}$ the external operators of the second kind for $V$.
\end{definition}
\begin{lemma}\label{lemma:exttopsecondindep}
	The external operators of the second kind have unique minimal shifts $x_1,\dots,x_n$ and $f(x_1),\dots,f(x_n)$ are linearly independent.
\end{lemma}
\begin{proof}
	Given $v_i$, $T^{v_i}$ has a unique minimal shift $x_i$ given by Lemma \ref{lemma:extopsecond}. Consider a linear relation $X=\sum_i \lambda_i x_i=0$. Suppose at first that $e_0,\dots,e_r$ are introverted edges of $\Phi_V$ that form a connected subset $\Lambda$ of $\Phi_V$, and call $v_1,\dots,v_r$ the internal vertices of $\Lambda$ (with the convention that $e_i\cap e_{i+1}=v_{i+1}$), and that at $v_i$, the smaller edge is $e_{i-1}$ and the bigger  is $e_i$. Then $\gamma_{v_i}$, as defined in Definition \ref{def:extopsecond}, is given by $e_{i}$. By Lemma \ref{lemma:extopsecond}, among the minimal shifts of external operators of the second kind, there is exactly one $x_i$ such that $f(x_i)(v_1)\neq 0$, namely the one corresponding to $T^{v_1}$ (since any other $\gamma_v$ would not contain $v_1$ as endpoint). Therefore $0=f(X)(v_1)=-2\lambda_i$ and thus $x_i$ appears with trivial coefficient in $X$. We can repeat the same reasoning in order for each $v_i$ to find that the corresponding minimal shift must not appear in $X$. Repeat this process for any other choice of introverted edges. Finally, take any $v$ in $\Phi_V$ that has at least one non introverted outgoing edge; then as before the only minimal shift such that $f(x_i)(v)\neq 0$ is the one corresponding to $T^{v}$ and thus following the same reasoning it must not appear in $X$.
\end{proof}
\begin{corollary}\label{cor:extoperators}
	Let $b_1,\dots,b_k$ be the external operators of $V$ (of both kinds); let $x_1,\dots,x_k$ be their unique minimal shift. Then $f(x_1),\dots,f(x_k)$ are linearly independent.
\end{corollary}
\begin{proof}
	Suppose the operators up to $b_n$ are of the first kind; then for any singular edge $e$, $f(x_i)(e)=0$ for all $i>n$. This implies that any linear dependence relation between the $f(x_i)$'s can only involve $i>n$ (since by Lemma \ref{lemma:exttopfirstindep} the first $n$ are linearly independent). However the $f(x_i)$'s for $i>n$ are linearly by Lemma \ref{lemma:exttopsecondindep}.
\end{proof}

\begin{definition}\label{def:intoperators}
	Consider $\gamma_1,\dots,\gamma_r$ all the maximal directed paths in $\Phi_V$; notice that they either end at a leaf of $\Phi_V$ or at an introverted edge. We will use these to define another set of operators but we first need to remove some of them. 

	Let $e_1,\dots,e_{n'}$ be the leaves of $\Phi_V$, and for each of them call $\gamma_{e_i}$ the maximal directed path ending in $e_i$ as in Lemma \ref{lemma:intopsecond}. 

	To these, we wish to add one maximal path ending at each introverted edge, but we need to make a choice. For each introverted edge $e$, there are exactly two maximal directed paths ending at $e$, each containing one of the endpoints $v,w$ of $e$ in their interior; we wish to remove one. Suppose that $\gamma_v$ contains $e$; then we remove the path that contains $v$ as an endpoint. If instead $\gamma_w$ contains $e$ we similarly remove the path that contains $w$ as an endpoint (notice that $\gamma_v$ and $\gamma_w$ cannot both contain $e$). If neither contains $e$, we simply remove one maximal path at random (see Figure \ref{fig:introoperator}). 

	Furthermore, for each extraverted edge $e$ of $\Phi_V$, we wish to remove one of these paths. To do this, choose $v$ the smaller endpoint of $e$, and call $\gamma_v$ the path defined in Lemma \ref{lemma:extopsecond}; one of the $\gamma_{e_i}$'s is going to equal $\gamma_v$ plus $e$, and we remove it from our collection (see Figure \ref{fig:extraoperator}) (notice that by construction this path was not removed by the previous step). Repeat the process for every extraverted edge.

	Renumber the remaining paths as $\gamma_{e_1},\dots,\gamma_{e_n}$, and define $d_{k+i}=T^{\gamma_{e_i}}$ as in Lemma \ref{lemma:intopsecond}.

	\begin{figure}
		\includegraphics[scale=0.4]{figures/extraoperator}
		\label{fig:extraoperator}
		\caption{If $v_1\succ v_2$, the definition removes the top orange path from the collection.}
	\end{figure}

	\begin{figure}
		\includegraphics[scale=0.7]{figures/introoperator}
		\label{fig:introoperator}
		\caption{An example of set of paths defining the operators. The blue straight paths define the external operators, while the orange curved paths define the internal operators.}
	\end{figure}

	Finally, let $e_1,\dots,e_m$ be the regular edges of $\Gamma$. Define $d_{k+n+i}:=T^{e_i}$ as in Lemma \ref{lemma:intopfirst}, so that we get operators $d_{k+1},\dots,d_{k+n+m}$, the first $n$ each corresponding to a maximal directed paths in $\Phi_V$, and the last $m$ corresponding to regular edges. Call these operators the \emph{internal operators} of $V$.
\end{definition}

\begin{lemma}\label{lemma:basisV}
	Let $d_{k+1},\dots,d_{k+n+m}$ be the internal operators of $V$, and choose a non-zero minimal shift for each of them; call them $y_{k+1},\dots,y_{k+n+m}$. Then $g(y_{k+1}),\dots,g(y_{k+n+m})$ are a basis for $g(V)$ over $\Q$ (hence $k+n+m=3g-3$).
\end{lemma}
\begin{proof}
	The fact that they are linearly independent is a direct and obvious consequence of Lemmas \ref{lemma:intopfirst}, \ref{lemma:intopsecond} and \ref{lemma:intopsecondintro}.

	We need to prove that $g(W)$ is spanned over $\Q$ by $g(y_{k+1}),\dots,g(y_{k+n+m})$, where $W$ is the smallest subspace of $\Z^\mathcal{E}$ that contains $V$. To see this, we just need to show that given $a_{k+1},\dots,a_{k+n+m}$ arbitrarily, there exists a $c\in W$ such that $c(e_i)=a_i$. We do so by using the equations defining $W$ to extend $a_{k+1},\dots,a_{k+n+m}$ to a coloring of $\Gamma$. Every regular or singular edge has its color given by either the $a_i$'s or the definition of $W$. The edges of $\Phi_V$ can be colored from the leaves and introverted edges inwards; notice that if $\Phi_V$ has an extraverted edge $e$, we removed one of the leaves or introverted edges reachable from $e$, therefore we can first determine the color of $e$ by working inwards on the other side, and then use $e$ to determine the color of the missing edge.
\end{proof}

\begin{remark}
	Notice that if $d_{i}$ corresponds to a regular edge, it has $2$ different non-zero minimal shifts with opposite signs, and thus its polytope of minimal shifts is given by a segment that contains $0$.
\end{remark}

The following lemma is the key reason for choosing the operators the way we did; we will use it to guarantee that in the recurrence relations we obtain from them, there are no cancellations among the minimal shifts.
\begin{lemma}\label{lemma:fglinindep}
	Let $b_1,\dots,b_k,d_{k+1},\dots,d_{3g-3}$ be the operators from Definitions \ref{def:extopfirst}, \ref{def:extopsecond} and \ref{def:intoperators}, and $y_1,\dots,y_{3g-3}$ be a non-zero minimal shift for each of them. Then the vectors $\xi_i:=(f(y_i),g(y_i))\in\Z^{N}$ are linearly independent.
\end{lemma}

\begin{proof}
	Suppose that $\Xi:=\sum_{i=1}^{3g-3} a_i \xi_i=0$. 

	First notice that if $e$ is a regular edge, and $d_j$ is the corresponding internal operator, then $f(y_j)=0$ and $g(y_j)=\pm2\delta_e$, and all other $y_i$'s have disjoint support from $\delta_e$; therefore $a_j=0$. Similarly, if $e$ is a singular edge, $\xi_i(e)=0$ unless $\xi_i$ is the minimal shift of an external operator of the first kind. Therefore by evaluating $\Xi$ on the subspace spanned by singular edges, we obtain that (by Lemma \ref{lemma:exttopfirstindep}) all those $\xi_i$'s must have trivial coefficient in $\Xi$.

	Therefore we only need to worry about external operators of the second kind and internal operators associated to a maximal directed path in $\Phi_V$.

	Now we introduce some notation that will greatly simplify the flow of the proof. For any $v\in \Phi_V$, we have the path $\gamma_v$ defined in Definition \ref{def:extopsecond}, the associated path operator, and the unique minimal shift which we will denote $y_v$. With a small abuse of notation, we will say that $y_v$ is the minimal shift of $\gamma_v$. Similarly, any maximal path in $\Phi_V$ among the ones defining the internal operators is determined by its final edge $e$; we call this path $\gamma_e$ and the minimal shift of the resulting operator $y_e$. Notice that $e$ must be either a leaf of $\Phi_V$ or an introverted edge. For any of these minimal shifts, call $\xi_v:=\left(f(y_v),g(y_v)\right)$ (and similarly for $\xi_e$). Therefore we need to consider $\Xi=\sum_e a_e \xi_e+\sum_v a_v\xi_v=0$; we say that $v$ or $e$ are \emph{in the support of $\Xi$} if its coefficient is non-zero in $\Xi$. 

	We break up the proof in several steps.


	\emph{Step 1: if the incoming edge to $v$ is directed, and no outgoing edges is introverted, then $v$ does not belong to the support of $\Xi$.}

	Based on the assumption, $v$ does not belong to a root or an extraverted edge; it also does not belong to any introverted edge. Then Lemmas \ref{lemma:intopsecond} and \ref{lemma:intopsecondintro} imply that for any $e$, $\xi_e(v)=0$; similarly Lemma \ref{lemma:extopsecond} implies that $\xi_{v'}(v)=0$ for $v\neq v'$. Therefore $0=\Xi(v)=-2a_v$ implies $a_v=0$.


	\emph{Step 2: if the incoming edge to $v$ is directed, and exactly one outgoing edge is introverted, then $v$ is not in the support of $\Xi$.}

	Suppose $e'$ is the introverted outgoing edge and $e$ is the other one (either a leaf or directed); then $\gamma_v=e$; call $w$ the other endpoint of $e'$. 

	If $\gamma_w$ does not contain $e'$, then no other $\gamma_{w'}$ does, which means that $0=\Xi(e')=-2a_{e'}=0$ and $0=\Xi(v)=-2a_v=0$ and we have the desired result. 

	Suppose instead that $\gamma_w=e'$: then by definition $\gamma_{e'}$ contains $w$ in its interior and $0=\Xi(e')=-2a_{e'}-2\sum a_{w'}$ where the sum runs over all $w'$s such that $\gamma_{w'}$ contains $e'$.  By evaluating $\Xi$ in $v$ we then obtain that $0=\Xi(v)=-2a_v-2a_{e'}-2\sum a_{w'}=-2a_v$ and $v$ is not in the support of $\Xi$. 


	\emph{Step 3: if the incoming edge to $v$ is directed, and both outgoing edges are introverted, then $v$ is not in the support of $\Xi$.}

	Call $e,e'$ the outgoing edges, and suppose that $e$ is larger than $e'$, so that $\gamma_v=e$. Then $\gamma_e$ has $v$ in its interior; suppose that $\gamma_{e'}$ contains $v$ as an endpoint. Call $W_{e'}$ the set of vertices such that $e'\subseteq \gamma_w$. For all $w\in W_{e'}$, $\gamma_{w}$ has $v$ as its endpoint, which means that $0=\Xi(v)=-2a_v-2a_{e'}-2\sum_{w\in W_{e'}}a_w$. From $0=\Xi(e')=-2a_{e'}-2\sum_{w\in W_{e'}}$ we find that $v$ does not belong to the support of $\Xi$. 

	If instead $\gamma_{e'}$ does not contain $v$ as an endpoint, then by Definition \ref{def:intoperators} $\gamma_w$ does not contain $v$, where $w$ is the other endpoint of $e'$. In this case, no $w'\neq v$ is such that $v$ is an endpoint of $\gamma_{w'}$ and $v$ is not in the support of $\Xi$ as before.

	To recap, at this step the only vertices that could belong to the support of $\Xi$ belong to roots or extraverted edges.

	\emph{Step 4: if $v$ is the larger endpoint of an extraverted edge, then $v$ does not belong to the support of $\Xi$.}

	Call $e$ the final edge of $\gamma_v$. When defining the operators we did not use $\gamma_e$; furthermore, any $w\neq v$ such that $e\subseteq\gamma_w$ is not in the support of $\Xi$. This is because if $\gamma_w\cap \gamma_v$ is non-empty then $\gamma_w\subseteq \gamma_v$ and thus $w$ has a directed incoming edge (therefore is not in the support by the previous steps). This means that $0=\Xi(e)=-2a_v$ and we have the desired result.

	\emph{Step 5: if $e$ is a leaf or an introverted edge, and $\gamma_e$ contains the larger endpoint of an extraverted edge in its interior, then $e$ does not belong to the support of $\Xi$.}

	By the previous steps there are no $w$'s in the support of $\Xi$ such that $e\subseteq \gamma_w$, which means that $0=\Xi(e)=-2a_e$ and $e$ does not belong to the support of $\Xi$.

	\emph{Step 6: no $v$ belongs to the support of $\Xi$.}

	The only cases left to check are when $v$ belongs to a root of $\Phi_V$, or when it is the smaller endpoint of an extraverted edge. We carry out the latter since the former will be identical.

	Let $e$ be the final edge of $\gamma_v$. If $e'\neq e$ and $v$ is in the interior of  $\gamma_{e'}$, then $e'$ is not in the support of $\Xi$. To see this, notice that there are no $w$'s in the support of $\Xi$ such that $e'\subseteq \gamma_w$ (following the same reasoning as Step 4), which means that $0=\Xi(e')=-2a_{e'}$. Therefore $0=\Xi(v)=-2a_v-4a_e$. 

	Then no $w\neq v$ such that $e\subseteq\gamma_w$ belongs to the support of $\Xi$. As usual if $e'\neq e$, $e$ is not contained in $\gamma_{e'}$. This means that $0=\Xi(e)=-2a_e-2a_v$, which combined with $-2a_v-4a_e=0$ implies that $v$ is not in the support of $\Xi$.

	\emph{Step 7: no $e$ belongs to the support of $\Xi$.}

	Because there are no $v$'s in the support of $\Xi$, and because $y_{e}(e')=0$ if $e\neq e'$, we have that $0=\Xi(e)=-2a_e$ and $e$ is not in the support of $\Xi$.

\end{proof}
\begin{corollary}\label{cor:linindep}
The elements $y_1,\dots,y_{3g-3}$ of Lemma \ref{lemma:fglinindep} are linearly independent.
\end{corollary}
\begin{lemma}\label{lemma:polytope}
	Suppose that among the internal operators $d_{k+1},\dots,d_{3g-3}$, the last $l$ correspond to the regular edges $e_{3g-3-l+1},\dots,e_{3g-3}$; denote with $x_j$ the unique minimal shift of the $j$-th operator for $j\leq 3g-3-l$. Consider the monomial $M=\prod_{i=1}^{k}b_i^{n_i}\prod_{j=k+1}^{3g-3}d_j^{n_j}$. Then the polytope of minimal shifts of $M$ is given by $$\sum_{i=1}^{3g-3-l}n_ix_i+\left\{\sum_{j=3g-2-l}^{3g-3}r_j\delta_{e_j},-2n_j\leq r_j\leq 2n_j\right\}$$.

\end{lemma}

\begin{proof}
	First notice that the operator $M'=\prod_{i=1}^{k}b_i^{n_i}\prod_{j=k+1}^{3g-3-l}d_j^{n_j}$ has a unique minimal shift equal to $x'=\sum_{i=1}^{3g-3-l}n_ix_i$; this can be proved by repeated applications of Lemma \ref{lemma:uniqueminimalshift}. Following this, notice that applying Lemma \ref{lemma:curveActions} repeatedly we can see that the polytope of minimal shifts of $d_{j}^{n_j}$ is a segment whose endpoints are $\pm2n_j\delta_{e_j}$; once again applying Lemma \ref{lemma:uniqueminimalshift} we obtain that the polytope of minimal shifts of $M'':=\prod_{j=3g-2-l}^{3g-3}d_j^{n_j}$ is $\left\{\sum_{j=3g-2-l}^{3g-3}r_j\delta_{e_j},-2n_j\leq r_j\leq 2n_j\right\}$. A final application of Lemma \ref{lemma:uniqueminimalshift} gives the desired result.
\end{proof}

\begin{corollary}\label{cor:polytope}
	Take $M_1,M_2$ two monomials as in Lemma \ref{lemma:polytope}, and call $\mathcal{P}_1,\mathcal{P}_2$ their respective polytopes of minimal shifts. Then:
	\begin{itemize}
		\item if $\mathcal{P}_1\cap \mathcal{P}_2\neq\emptyset$, then $M_1$ and $M_2$ have the same multidegree up to variable $d_{3g-3-l}$ (i.e. except for variables corresponding to regular edges);
		\item if $\mathcal{P}_1=\mathcal{P}_2$ then $M_1=M_2$.

	\end{itemize}
\end{corollary}
\begin{proof}
	Call $(n_1,\dots,n_{3g-3})$ the multidegree for $M_1$, and $(s_1,\dots,s_{3g-3})$ the multidegree for $M_2$.
	Suppose that there are $y_1,y_2$ belonging to $\mathcal{P}_1,\mathcal{P}_2$ respectively and that $y_1=y_2$. We know from Lemma \ref{lemma:fglinindep} that the $x_i$'s and the $\delta_{e_j}$'s are linearly independent, which implies that $n_i=s_i$ for all $i\leq 3g-3-l$, proving the first part of the lemma. If furthermore $\mathcal{P}_1=\mathcal{P}_2$ then we can repeat the same argument for every vertex of this polytope to prove that the rest of the multidegrees must coincide too.
\end{proof}

\begin{lemma}\label{lemma:effectivemonomial}
	Let $V$ be a simple barely admissible subspace, and suppose $M_1,M_2$ are operators with the following property: there exist $U_1,U_2$, each a finite union of barely admissible subspaces, such that
	\begin{itemize}
		\item for any $c\in \Delta\setminus U_i$, $c$ is effective for $M_i$;
		\item $U_i$ is transverse to $V$.
	\end{itemize}

	 Then there exists $U\subsetneq \Delta$ finite union of barely admissible subspaces such that for any $c\in \Delta\setminus U$, $c$ is effective for $M_1M_2$ and $U$ is transverse to $V$.
\end{lemma}
\begin{proof}
	Let $x_1,\dots,x_n$ be the minimal shifts of $M_1$ and $y_1,\dots,y_r$ the shifts of $M_2$, with $y_1$ minimal. We show that $U$ can be chosen as the union of all subspaces $U_2$ and $y_j-y_1+U_1$. If $c$ is effective for $M_2$, and $c+y_j-y_1$ is effective for $M_1$ for all $j$, then $c$ is effective for $M_1M_2$, by simply applying $M_1$ to each summand in $M_2\cdot \phi_{c+y_1}$.

\end{proof}

\begin{corollary}\label{cor:effectivemonomial}
	Let $W$ be a subspace of $\Z^{\mathcal{E}}$, and let $V$ be the smallest simple barely admissible subspace containing $W$. Let $M$ be a monomial in the operators associated to $V$; then there exists a subset $U\subsetneq W$, consisting of a finite union of barely admissible subspaces, such that for any $c\in W\setminus U$, $c$ is effective for $M$.
\end{corollary}
\begin{proof}
	The case of $W=V$ is an immediate consequence of Lemmas \ref{lemma:extopfirst}, \ref{lemma:extopsecond}, \ref{lemma:intopfirst}, \ref{lemma:intopsecond}, \ref{lemma:intopsecondintro} establishing the result for each variable, and \ref{lemma:effectivemonomial} establishing the result for a product.
 The general case follows at once, since $W$ cannot be contained in $U$ by minimality of $V$.
\end{proof}

\subsection{Proof of the inductive case}\label{sec:induction2}

\begin{proof}[Proof of the inductive step in Case 2]
	The proof follows the same general lines of Case 1. We set $n=3g-3$ for convenience. Recall that we have a collection $(V_i)_{i\in I}$ of subspaces of $\Z^{\mathcal{E}}=\Z^{n}$, each of codimension at least $1$, such that $$\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c\in \Delta \setminus \underset{s\in S}{\bigcup}V_s\rbrace \ \textrm{is finite dimensional}$$

	and that we want to prove that we can find $i\in I$, and $V_i^j\subsetneq V_i$ for $j\in S$ such that the collection $(V_s)_{s\in I\setminus i}\cup (V_i^j)_{j\in S}$ also satisfies the above condition.

	To start, pick $V_0$ a subspace of minimal codimension among the $V_i$'s; call $\widetilde{V_0}$ the smallest simple barely admissible subspace that contains $V_0$. Recall that $\widetilde{V_0}$ comes with maps $f,g$, with a regular, singular and flow subgraphs, with the internal and external operators of Lemma \ref{lemma:fglinindep}, and with an order on the edges and vertices of the flow subgraph.

	 Among the $V_i$'s there might be parallels of $V_0$; our first order of business is to pick correctly one of these subspaces. For any $V_i$ parallel to $V_0$, consider $f(\widetilde{V_i})$ where $\widetilde{V_i}$ is the smallest simple barely admissible subset containing $V_i$ (notice that clearly $\widetilde{V_i}$ and $\widetilde{V_0}$ are parallel). Replace $V_0$ with one of the parallel subspaces that maximize $f(\widetilde{V_i})$ (notice that there could be more than one). Now let $e_1,\dots,e_{r}$ the regular edges and the final edges of internal operators of $\widetilde{V_0}$. Then $\delta_{e_1},\dots,\delta_{e_r}$ form a basis for $g(\widetilde{V_0})$ (in particular $r=\widetilde{k}$). We pick a subset $J\subseteq \{1,\dots,\widetilde{k}\}$ applying Lemma \ref{lemma:lin_alg} to $g(V_0)\subseteq g(\widetilde{V_0})$. Any translate of $V_0$ contained in $\widetilde{V_0}$ will be of the form $V_0+\sum_{j\in J} x_j\delta_{e_j}$. Among these subspaces that belong to $(V_i)_{i\in I}$, we redefine $V_0$ to be the one maximizing $\left(g(x_j)\right)_{j\in J}$ in the lexicographic order.

	Finally pick $J'\subseteq \{1,\dots,n\}$ according to Lemma \ref{lemma:non-vanishing_poly}; let $a_i:=T^{\alpha_i}$. Let $b_1,\dots,b_{n-\widetilde{k}}$ be the external operators of $\widetilde{V_0}$. Let $d_1,\dots,d_{\widetilde{k}}$ be the internal operators of $\widetilde{V_0}$, numbered so that $d_i$ corresponds to the edge $e_i$.


	 For any $l\in \{1,\dots,\widetilde{k}\}\setminus J$ we consider the family of operators
	$$F_l:=\{a_{j'}\}_{j'\in J'}\cup \{d_j\}_{j\in J\cup \{l\}}\cup\{b_1,\dots,b_{n-\widetilde{k}}\}.$$

	For any $l,$ the set $F_l$ contains exactly $3g-2$ multicurve operators, therefore by Lemma \ref{lem:linDep} there is a non-zero polynomial $P_l$ such that $P_l(a_{j'},d_j,b_i)\cdot\varphi_c=0$ as an element of $\Sk^{\overline{\lambda}}(M)$ for any $c\in \Delta$.

	Let $D_l$ be the total degree of $P_l$ in the variables $b_i$ and $d_j$; consider $W\subseteq V_0$ the subset with the following properties:
	\begin{itemize}
		\item $c\in W$ if $c$ is not effective for at least one monomial of $P_l$; or 
		\item $c\in W$ if $c$ is at distance less than or equal to $4D_l$ from any other subspace $V_i$, with $i\in I$, such that $V_i$ is not parallel to $V_0$.
	\end{itemize}

	By Corollary \ref{cor:effectivemonomial}, $W$ is a finite union of subspaces of $V_0$ of codimension at least $1$. Call $W_0:=V\setminus W$.

	\textbf{Claim:} For any $l\in \{1,\dots,k\}\setminus J$ and $c\in W_0$, we have a relation of the form

	$$ R_{d_l}(A,A^{c_{i_1}},\ldots , A^{c_{i_k}})\varphi_{c+d_l u_l} + \ldots + R_{-d_l}(A,A^{c_{i_1}},\ldots , A^{c_{i_k}})\varphi_{c-d_l u_l} \equiv 0,$$
	where the vector $u_l$ is a generator of the line $D_l$ given in Lemma \ref{lemma:lin_alg}, $d_l$ is an integer, $R_{-d_l}$ is a non-zero polynomial in $k+1$ variables, and $\equiv$ is equality up to an element of 
	$$E_0=\mathrm{Span}_{\Q(A,\overline{\lambda})}\lbrace \varphi_c \ | \ c \in \Delta \setminus \underset{s\in S}{\bigcup} V_s \rbrace.$$

	\begin{proof}[Proof of the Claim]
		We assume for simplicity that no final edges of the internal operators are loop edges. If any final edge is a loop edge, it simply changes some of the following formulas by removing a factor of $2$ in some minimal shift (since the minimal shift of the curve operator of a loop edge is $-\delta_e$ rather than $-2\delta_e$). This is inconsequential and only makes formulas more awkward.

		Consider $M$ a monomial of $P_l$. The $a_i$'s act on $\varphi_c$ as multiplication by a scalar, so $M\cdot \varphi_c=R(A,A^{c_{i_1}},\dots,A^{c_{i_k}}) M'\cdot \varphi_c$ where $M'$ is simply $M$ with all $a_i$ variables removed. Rewrite all monomials of $P_l$ like this, and call $M_1,\dots,M_r$ the resulting monomials. Let $\mathcal{P}_1,\dots,\mathcal{P}_r$ their polytopes of minimal shifts; by Lemma \ref{lemma:polytope}, $f(\mathcal{P}_i)=f(x_i)$ for some $x_i$; select a monomial $M_i$ following these three criteria, in order of importance:
		\begin{itemize}
			\item $f(x_i)$ minimal;
			\item $g(x_i)$ minimal;
			\item maximal degree in $d_l$;
			\item maximal degree in the other $d_j$s, in the lexicographic order.
		\end{itemize}

		Let $n_j$ be the degree of $M_i$ in $d_j$. 

		By Lemma \ref{lemma:polytope} and Corollary \ref{cor:polytope} there is no other monomial $M_r$ of $P_r$ that contains the shifts $x_\pm:=x_i \pm 2n_l\delta_{e_l}-\sum_{j\neq l} 2n_j\delta_{e_j}$, where the sum is over regular edges (notice that if $e_l$ is not regular, $x_+$ is not a minimal shift). For any $c\in W_0$, let $\widetilde{c}:=c-x_i+\sum_{j\neq l} 2n_j\delta_{e_j}$.

		For any monomial $M_r$, if $x_r\neq x_i$, $M_r\cdot \varphi_{\widetilde{c}}\in E_0$. To see this, suppose that there is a shift $x$ such that $\varphi_{\widetilde{c}+x}\in \underset{s\in S}{\bigcup} V_s$. By construction $\widetilde{c}+x$ cannot belong to one of the $V_s$ that are not parallel to $V_0$, since the distance of $c$ from any of these is more than $4D_l$, and both $x$ and $c-\widetilde{c}$ have $L^1$-norm less than or equal to $2D_l$. Therefore $V_s$ must be parallel to $V_0$; however in this case because of our choice of $V_0$, we would have either $$f(c)\geq f(\widetilde{c}+x)=f(c)+f(x)-f(x_i)\geq f(c)+f(x_r)-f(x_i)>f(c)$$
		by minimality (if $f(x)>f(x_i)$), or if $f(x)=f(x_i)$, then $f(x)$ is minimal and we would have $$g(c)\geq g(\widetilde{c}+x)=g(c)+g(x)-g(x_i)\geq g(c)+g(x_r)-g(x_i)>g(c).$$

		If instead $x_r=x_i$, $$M_r\cdot \varphi_{\widetilde{c}}=R_{n'_l}\varphi_{c+2n'_l \delta_{e_l}}+R_{-n'_l}\varphi_{c-2n'_l \delta_{e_l}}+\sum_{j=-n'_l+1}^{n'_l-1}R_{j}\varphi_{c+2j\delta_{e_l}}+X$$

		with $X\in E_0$ and $R_{-n_r}\neq 0$, where $n'_j$ is the degree of $M_r$ in the variable indexed by $j$. To see this, notice that if $x$ is a non-minimal shift, then we can apply the above reasoning to show that $\varphi_{\widetilde{c}+x}\in E_0$. Therefore the only summands in $M_r\cdot\varphi_{\widetilde{c}}$ are the ones corresponding to the minimal shifts of $M_r$. Take one such minimal shift $x:=x_i+\sum_{j} \pm2m_j\delta_{e_j}$ with $m_j\leq n'_j$ the degree of $M_r$ in the variable $d_j$. If $m_j<n_j$ for any $j\neq l$, then $\widetilde{c}+x\in E_0$, using the same reasoning as before. Therefore the only minimal shifts for which $\varphi_{\widetilde{c}+x}\in V_0$ are $$x_l:=x_i \pm 2m_l\delta_{e_l}-\sum_{j\neq l} 2n_j\delta_{e_j}$$
		for $-n_l\leq m_l\leq n_l$, which gives the desired result.



		Combining these two facts, we obtain that 		
		$$P_l\cdot \varphi_{\widetilde{c}}=R_{n_l}\varphi_{c+2n_l \delta_{e_l}}+R_{-n_l}\varphi_{c-2n_l \delta_{e_l}}+\sum_{j=-n_l+1}^{n_l-1}R_{j}\varphi_{c+2j\delta_{e_j}}+X$$

		where $R_{- n_l}$ is a non-zero Laurent polynomial evaluated in $A,A^{c_1},\dots,A^{c_n}$ as before, and $X\in E_0$.

	\end{proof}

	From here, the proof of the inductive case proceeds verbatim as in Case 1.
\end{proof}
